import java.nio.file.*;import java.util.*;import javax.tools.*;import javax.lang.model.element.*;import javax.lang.model.type.*;import com.sun.source.tree.*;import com.sun.source.util.*;
/** Full-source javac attribution; unresolved legacy names never count as native resolution. */
public class TooltipScanner {
 static String b(String s){return Base64.getEncoder().encodeToString(s.getBytes(java.nio.charset.StandardCharsets.UTF_8));}
 public static void main(String[] args)throws Exception{
  JavaCompiler c=ToolProvider.getSystemJavaCompiler();DiagnosticCollector<JavaFileObject>d=new DiagnosticCollector<>();StandardJavaFileManager f=c.getStandardFileManager(d,null,null);JavacTask task=(JavacTask)c.getTask(null,f,d,Arrays.asList("-proc:none","-source","8","-classpath",args[1],"-Xmaxerrs","100000"),null,f.getJavaFileObjectsFromStrings(Files.readAllLines(Paths.get(args[0]))));Trees trees=Trees.instance(task);List<CompilationUnitTree>units=new ArrayList<>();for(CompilationUnitTree u:task.parse())units.add(u);task.analyze();
  for(CompilationUnitTree u:units){String source=u.getSourceFile().getCharContent(true).toString();new TreePathScanner<Void,Void>(){
   String text(Tree t){long a=trees.getSourcePositions().getStartPosition(u,t),z=trees.getSourcePositions().getEndPosition(u,t);return a<0||z<a?"":source.substring((int)a,(int)z);}
   MethodTree method(){for(TreePath p=getCurrentPath();p!=null;p=p.getParentPath())if(p.getLeaf() instanceof MethodTree)return (MethodTree)p.getLeaf();return null;}
   String branch(){for(TreePath p=getCurrentPath();p!=null;p=p.getParentPath())if(p.getLeaf() instanceof IfTree)return text(p.getLeaf());return "";}
   TypeMirror implicit(){for(TreePath p=getCurrentPath();p!=null;p=p.getParentPath())if(p.getLeaf() instanceof ClassTree){Element e=trees.getElement(p);if(e instanceof TypeElement){if(gui(e.asType()))return e.asType();for(Element m:task.getElements().getAllMembers((TypeElement)e))if(m.getSimpleName().contentEquals("drawCreativeTabHoveringText")||m.getSimpleName().contentEquals("func_146283_a")||m.getSimpleName().contentEquals("drawHoveringText"))return e.asType();}}return null;}
   boolean gui(TypeMirror t){TypeElement base=task.getElements().getTypeElement("net.minecraft.client.gui.GuiScreen");return t!=null&&t.getKind()==TypeKind.DECLARED&&base!=null&&task.getTypes().isSubtype(task.getTypes().erasure(t),task.getTypes().erasure(base.asType()));}
   public Void visitMethod(MethodTree n,Void v){String name=n.getName().toString();if(name.equals("drawCreativeTabHoveringText")||name.equals("func_146283_a")||name.equals("drawHoveringText")||name.equals("drawGradientRect")){Element e=trees.getElement(getCurrentPath());System.out.println("DECL\t"+Paths.get(u.getSourceFile().toUri())+"\t"+b(String.valueOf(e==null?null:e.getEnclosingElement()))+"\t"+b(n.toString()));}return super.visitMethod(n,v);}
   public Void visitAssignment(AssignmentTree n,Void v){String name=n.getVariable().toString();if(name.endsWith("zLevel")){MethodTree m=method();Element e=trees.getElement(new TreePath(getCurrentPath(),n.getVariable()));System.out.println("Z\t"+Paths.get(u.getSourceFile().toUri())+"\t"+b(String.valueOf(e==null?null:e.getEnclosingElement()))+"\t"+b(m==null?"":text(m))+"\t"+b(text(n))+"\t"+b(branch()));}return super.visitAssignment(n,v);}
   public Void visitMethodInvocation(MethodInvocationTree n,Void v){ExpressionTree s=n.getMethodSelect();String name=s instanceof MemberSelectTree?((MemberSelectTree)s).getIdentifier().toString():s.toString();if(!Arrays.asList("func_146283_a","drawHoveringText","drawCreativeTabHoveringText").contains(name))return super.visitMethodInvocation(n,v);
    ExpressionTree receiver=s instanceof MemberSelectTree?((MemberSelectTree)s).getExpression():null;TypeMirror type=receiver==null?implicit():trees.getTypeMirror(new TreePath(new TreePath(getCurrentPath(),s),receiver));List<String>types=new ArrayList<>(),values=new ArrayList<>();for(ExpressionTree a:n.getArguments()){types.add(String.valueOf(trees.getTypeMirror(new TreePath(getCurrentPath(),a))));values.add(b(text(a)));}Element target=trees.getElement(getCurrentPath());String resolved=target instanceof ExecutableElement?target.getEnclosingElement()+":"+target:"unresolved";MethodTree m=method();long end=trees.getSourcePositions().getEndPosition(u,s);List<String>overrides=new ArrayList<>();
    if(type!=null&&type.getKind()==TypeKind.DECLARED){Element e=task.getTypes().asElement(type);if(e instanceof TypeElement)for(Element member:task.getElements().getAllMembers((TypeElement)e))if(member.getKind()==ElementKind.METHOD&&(member.getSimpleName().contentEquals("drawCreativeTabHoveringText")||member.getSimpleName().contentEquals("func_146283_a")||member.getSimpleName().contentEquals("drawHoveringText")))overrides.add(member.getEnclosingElement()+":"+member);}
    System.out.println("CALL\t"+Paths.get(u.getSourceFile().toUri())+"\t"+(end-name.length())+"\t"+end+"\t"+name+"\t"+b(receiver==null?"<implicit>":text(receiver))+"\t"+b(String.valueOf(type))+"\t"+gui(type)+"\t"+n.getArguments().size()+"\t"+b(types.toString())+"\t"+String.join(",",values)+"\t"+b(resolved)+"\t"+b(m==null?"":text(m))+"\t"+b(overrides.toString())+"\t"+b(text(n))+"\t"+b(branch()));
    return super.visitMethodInvocation(n,v);
   }
  }.scan(u,null);}
  System.err.println("Full-source attribution diagnostics (not a successful mod compile): "+d.getDiagnostics().stream().filter(x->x.getKind()==Diagnostic.Kind.ERROR).count());
 }
}
